function* greet() {
  console.log("Start");

  yield "Hello";

  console.log("Middle");

  yield "World";

  console.log("End");
}

const generator = greet();

console.log(generator.next().value);
// Start
// Hello

console.log(generator.next().value);
// Middle
// World

console.log(generator.next().value);
// End
// undefined

const iterator = {
  count: 1,

  next() {
    if (this.count <= 3) {
      return {
        value: this.count++,
        done: false
      };
    }

    return {
      value: undefined,
      done: true
    };
  }
};

console.log(iterator.next());
// { value: 1, done: false }

console.log(iterator.next());
// { value: 2, done: false }

console.log(iterator.next());
// { value: 3, done: false }

console.log(iterator.next());
